package store

import (
	"context"
	"encoding/json"
	"errors"
	"sync"
	"testing"
)

func TestPromoteCopiesGraySnapshotIntoEffectiveVersion(t *testing.T) {
	st, err := Open(t.TempDir() + "/store.db")
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer st.Close()
	ctx := context.Background()

	publishVersion(t, st, "payments", "prod", "", mustItems(t, "a", `"old"`, "n", "1"))
	publishVersion(t, st, "payments", "prod", "canary",
		mustItems(t, "a", `"new"`, "n", "1.0", "flag", "true", "empty", "null"))

	promoted, err := st.Promote(ctx, "payments", "prod", 2)
	if err != nil {
		t.Fatalf("promote: %v", err)
	}
	if promoted.Version != 3 {
		t.Fatalf("version = %d, want 3", promoted.Version)
	}
	if promoted.EffectiveGrayTag() != "" {
		t.Fatalf("promoted version must not carry a gray tag: %q", promoted.EffectiveGrayTag())
	}
	if promoted.PromotionSource() != 2 {
		t.Fatalf("promotionOf = %d, want 2", promoted.PromotionSource())
	}
	if promoted.RollbackSource() != 0 {
		t.Fatalf("promotion rollbackOf = %d, want 0", promoted.RollbackSource())
	}

	effective, err := st.EffectiveVersion(ctx, "payments", "prod")
	if err != nil {
		t.Fatalf("effective: %v", err)
	}
	if effective != 3 {
		t.Fatalf("effective = %d, want 3 after promotion", effective)
	}

	items, err := st.Items(ctx, "payments", "prod", 3)
	if err != nil {
		t.Fatalf("items: %v", err)
	}
	want := map[string]string{"a": `"new"`, "n": "1.0", "flag": "true", "empty": "null"}
	if len(items) != len(want) {
		t.Fatalf("items = %v, want %v", items, want)
	}
	for name, value := range want {
		if string(items[name]) != value {
			t.Fatalf("item %s = %s, want %s", name, items[name], value)
		}
	}

	versions, err := st.ListVersions(ctx, "payments", "prod")
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	if len(versions) != 3 {
		t.Fatalf("history length = %d, want 3", len(versions))
	}
	source := versions[1]
	if !source.GrayTag.Valid || source.GrayTag.String != "canary" || source.PromotionOf.Valid {
		t.Fatalf("source version must stay untouched: %+v", source)
	}
	if versions[0].PromotionOf.Valid || versions[0].RollbackOf.Valid {
		t.Fatalf("normal release must not carry promotionOf/rollbackOf")
	}
	target := versions[2]
	if target.GrayTag.Valid || !target.PromotionOf.Valid || target.PromotionOf.Int64 != 2 || target.RollbackOf.Valid {
		t.Fatalf("promoted metadata = %+v", target)
	}
}
package store

import (
	"context"
	"database/sql"
	"path/filepath"
	"testing"

	_ "modernc.org/sqlite"
)

func TestOpenMigratesLegacyDatabaseAndPromotionOfIsNull(t *testing.T) {
	path := filepath.Join(t.TempDir(), "legacy.db")
	legacy, err := sql.Open("sqlite", path)
	if err != nil {
		t.Fatalf("open legacy: %v", err)
	}
	_, err = legacy.Exec(`
CREATE TABLE service_metadata (
	key   TEXT PRIMARY KEY,
	value TEXT NOT NULL
);
CREATE TABLE config_versions (
	namespace   TEXT NOT NULL,
	environment TEXT NOT NULL,
	version     INTEGER NOT NULL,
	gray_tag    TEXT,
	rollback_of INTEGER,
	created_at  TEXT NOT NULL,
	PRIMARY KEY (namespace, environment, version),
	FOREIGN KEY (namespace, environment, rollback_of)
		REFERENCES config_versions(namespace, environment, version)
);
CREATE TABLE config_items (
	namespace   TEXT NOT NULL,
	environment TEXT NOT NULL,
	version     INTEGER NOT NULL,
	name        TEXT NOT NULL,
	value_json  TEXT NOT NULL,
	PRIMARY KEY (namespace, environment, version, name),
	FOREIGN KEY (namespace, environment, version)
		REFERENCES config_versions(namespace, environment, version)
);
CREATE INDEX idx_config_versions_global ON config_versions(version);
INSERT INTO config_versions (namespace, environment, version, gray_tag, rollback_of, created_at)
	VALUES ('legacy', 'prod', 1, NULL, NULL, '2026-01-01T00:00:00Z');
INSERT INTO config_items (namespace, environment, version, name, value_json)
	VALUES ('legacy', 'prod', 1, 'a', '"1"');
`)
	if err != nil {
		t.Fatalf("seed legacy schema: %v", err)
	}
	if err := legacy.Close(); err != nil {
		t.Fatalf("close legacy: %v", err)
	}

	st, err := Open(path)
	if err != nil {
		t.Fatalf("open migrated store: %v", err)
	}
	defer st.Close()
	ctx := context.Background()

	v, err := st.GetVersion(ctx, "legacy", "prod", 1)
	if err != nil {
		t.Fatalf("read legacy version: %v", err)
	}
	if v.PromotionOf.Valid {
		t.Fatalf("legacy version promotionOf = %d, want null", v.PromotionOf.Int64)
	}
	if v.RollbackOf.Valid {
		t.Fatalf("legacy rollbackOf must stay null")
	}
	items, err := st.Items(ctx, "legacy", "prod", 1)
	if err != nil {
		t.Fatalf("read legacy items: %v", err)
	}
	if string(items["a"]) != `"1"` {
		t.Fatalf("legacy item = %s", items["a"])
	}

	promoted, err := st.Promote(ctx, "legacy", "prod", 1)
	if err == nil {
		t.Fatalf("promoting a legacy full release must fail, got %+v", promoted)
	}
	publishVersion(t, st, "legacy", "prod", "canary", mustItems(t, "a", `"2"`))
	promoted, err = st.Promote(ctx, "legacy", "prod", 2)
	if err != nil {
		t.Fatalf("promote on migrated db: %v", err)
	}
	if promoted.Version != 3 || promoted.PromotionSource() != 2 {
		t.Fatalf("promoted = %d source %d", promoted.Version, promoted.PromotionSource())
	}
	effective, err := st.EffectiveVersion(ctx, "legacy", "prod")
	if err != nil {
		t.Fatalf("effective: %v", err)
	}
	if effective != 3 {
		t.Fatalf("effective = %d, want 3", effective)
	}
}

