	return "/historical-effective-configs?" + query.Encode()
}

// newHistoricalTestRouter opens a router backed by a SQLite file so tests can rewrite
// created_at through a second connection and make point-in-time queries deterministic.
func newHistoricalTestRouter(t *testing.T) (*store.Store, string, http.Handler) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "service.db")
	st, err := store.Open(path)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return st, path, NewRouter(st)
}

func setVersionCreatedAt(t *testing.T, dbPath, ns, env string, version int, createdAt string) {
	t.Helper()
	db, err := sql.Open("sqlite", dbPath)
	if err != nil {
