	}
	defer db.Close()
	if _, err := db.Exec(
		`UPDATE config_versions SET created_at = ? WHERE namespace = ? AND environment = ? AND version = ?`,
		createdAt, ns, env, version); err != nil {
		t.Fatalf("rewrite created_at: %v", err)
	}
}

type historicalResponse struct {
	Namespace        string                     `json:"namespace"`
	Environment      string                     `json:"environment"`
	AsOf             string                     `json:"asOf"`
	EffectiveVersion *int64                     `json:"effectiveVersion"`
	Version          *VersionInfo               `json:"version"`
	Items            map[string]json.RawMessage `json:"items"`
}

func decodeHistorical(t *testing.T, recorder interface{ Result() *http.Response }) historicalResponse {
	t.Helper()
	return historicalResponse{}
}

func TestHistoricalEffectiveSelectsFullReleasesAtPointInTime(t *testing.T) {
	_, dbPath, handler := newHistoricalTestRouter(t)
	publish(t, handler, "payments", "prod", "", map[string]any{"a": "v1"})
	publish(t, handler, "payments", "prod", "canary", map[string]any{"a": "gray"})
	publish(t, handler, "payments", "prod", "", map[string]any{"a": "v3"})
	publish(t, handler, "payments", "prod", "canary", map[string]any{"a": "gray2"})
	publish(t, handler, "payments", "prod", "", map[string]any{"a": "v5"})
	setVersionCreatedAt(t, dbPath, "payments", "prod", 1, "2026-10-01T10:00:00Z")
	setVersionCreatedAt(t, dbPath, "payments", "prod", 2, "2026-10-01T10:05:00Z")
	setVersionCreatedAt(t, dbPath, "payments", "prod", 3, "2026-10-01T10:10:00Z")
	setVersionCreatedAt(t, dbPath, "payments", "prod", 4, "2026-10-01T10:15:00Z")
	setVersionCreatedAt(t, dbPath, "payments", "prod", 5, "2026-10-01T10:20:00Z")

	cases := []struct {
		name           string
		asOf           string
		wantVersion    int64
		wantItem       string
		wantEffective  bool
		wantNormalized string
	}{
		{"before first full release", "2026-10-01T09:59:59Z", 0, "", false, "2026-10-01T09:59:59Z"},
		{"exact first full release", "2026-10-01T10:00:00Z", 1, `"v1"`, false, "2026-10-01T10:00:00Z"},
		{"inside gray window", "2026-10-01T10:05:59Z", 1, `"v1"`, false, "2026-10-01T10:05:59Z"},
		{"exact second full release", "2026-10-01T10:10:00Z", 3, `"v3"`, false, "2026-10-01T10:10:00Z"},
		{"after later gray", "2026-10-01T10:15:30Z", 3, `"v3"`, false, "2026-10-01T10:15:30Z"},
		{"latest full release", "2027-01-01T00:00:00Z", 5, `"v5"`, true, "2027-01-01T00:00:00Z"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			recorder := doRequest(t, handler, http.MethodGet, historicalPath("payments", "prod", tc.asOf), nil)
			if recorder.Code != http.StatusOK {
				t.Fatalf("status = %d body = %s", recorder.Code, recorder.Body.String())
			}
			var body historicalResponse
			if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
				t.Fatalf("decode: %v", err)
			}
			if body.Namespace != "payments" || body.Environment != "prod" {
				t.Fatalf("scope = %s/%s", body.Namespace, body.Environment)
			}
			if body.AsOf != tc.wantNormalized {
				t.Fatalf("asOf = %s, want %s", body.AsOf, tc.wantNormalized)
			}
			if tc.wantVersion == 0 {
				if body.EffectiveVersion != nil || body.Version != nil {
					t.Fatalf("expected null version fields, got %+v / %+v", body.EffectiveVersion, body.Version)
				}
				if len(body.Items) != 0 {
					t.Fatalf("items = %v, want empty object", body.Items)
				}
				return
			}
			if body.EffectiveVersion == nil || *body.EffectiveVersion != tc.wantVersion {
				t.Fatalf("effectiveVersion = %v, want %d", body.EffectiveVersion, tc.wantVersion)
			}
			if body.Version == nil || body.Version.Version != tc.wantVersion {
				t.Fatalf("version = %+v, want %d", body.Version, tc.wantVersion)
			}
			if body.Version.GrayTag != nil {
				t.Fatalf("historical effective version must not carry a gray tag: %v", body.Version.GrayTag)
			}
			if body.Version.Effective != tc.wantEffective {
				t.Fatalf("effective flag = %v, want %v", body.Version.Effective, tc.wantEffective)
			}
			if string(body.Items["a"]) != tc.wantItem {
				t.Fatalf("item = %s, want %s", body.Items["a"], tc.wantItem)
			}
		})
	}
}

